import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused BiasAdd + Hardtanh + Mish kernel
fused_activation_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_bias_activation_kernel(
    const float* input, const float* bias, float* output,
    int batch_size, int out_features
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_features) return;

    int batch = idx / out_features;
    int feat = idx % out_features;

    float x = input[idx] + bias[feat];
    x = fmaxf(fminf(x, 1.0f), -1.0f); // Hardtanh

    // Mish: x * tanh(softplus(x))
    float sp = log1pf(expf(x));
    float tanh_sp = tanhf(sp);
    output[idx] = x * tanh_sp;
}

torch::Tensor fused_bias_activation_cuda(
    torch::Tensor input, torch::Tensor bias
) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int batch_size = input.size(0);
    int out_features = input.size(1);

    dim3 block(256);
    dim3 grid((num_elements + block.x - 1) / block.x);

    fused_bias_activation_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_features
    );

    return output;
}
"""

# GroupNorm kernel
groupnorm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>

namespace cg = cooperative_groups;

template<typename T>
__global__ void group_norm_kernel(
    const T* input, const T* gamma, const T* beta, T* output,
    int batch_size, int num_groups, int channels_per_group, float eps
) {
    int group_id = blockIdx.y;
    int batch_id = blockIdx.x;
    int tid = threadIdx.x;

    extern __shared__ float smem[];
    float* mean_shared = smem;
    float* var_shared = smem + 1;

    const int offset = (batch_id * num_groups + group_id) * channels_per_group;
    const T* group_input = input + offset;
    T* group_output = output + offset;

    // Compute mean and variance
    float sum = 0.0f, sq_sum = 0.0f;
    for (int i = tid; i < channels_per_group; i += blockDim.x) {
        float val = group_input[i];
        sum += val;
        sq_sum += val * val;
    }

    // Block-wide reduction
    cg::thread_block block = cg::this_thread_block();
    sum = cg::reduce(block, sum, cg::plus<float>());
    sq_sum = cg::reduce(block, sq_sum, cg::plus<float>());

    if (tid == 0) {
        float mean = sum / channels_per_group;
        float var = (sq_sum / channels_per_group) - (mean * mean);
        *mean_shared = mean;
        *var_shared = rsqrtf(var + eps);
    }
    block.sync();

    // Normalize and apply gamma/beta
    float mean = *mean_shared;
    float inv_std = *var_shared;
    for (int i = tid; i < channels_per_group; i += blockDim.x) {
        float val = group_input[i];
        float normalized = (val - mean) * inv_std;
        group_output[i] = gamma[group_id * channels_per_group + i] * normalized + beta[group_id * channels_per_group + i];
    }
}

torch::Tensor group_norm_cuda(
    torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
    int num_groups, float eps=1e-5
) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int channels = input.size(1);
    int channels_per_group = channels / num_groups;

    dim3 blocks(batch_size, num_groups);
    int threads = 256;
    size_t smem = 2 * sizeof(float);

    group_norm_kernel<float><<<blocks, threads, smem>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_groups,
        channels_per_group,
        eps
    );

    return output;
}
"""

# Load CUDA extensions
fused_activation = load_inline(
    name='fused_activation',
    cpp_sources='torch::Tensor fused_bias_activation_cuda(torch::Tensor input, torch::Tensor bias);',
    cuda_sources=fused_activation_source,
    functions=['fused_bias_activation_cuda'],
    verbose=True
)

groupnorm = load_inline(
    name='groupnorm',
    cpp_sources='torch::Tensor group_norm_cuda(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int num_groups, float eps);',
    cuda_sources=groupnorm_source,
    functions=['group_norm_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, bias_shape, num_groups):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.num_groups = num_groups
        self.groupnorm_weight = nn.Parameter(torch.ones(out_features))
        self.groupnorm_bias = nn.Parameter(torch.zeros(out_features))

    def forward(self, x):
        x = self.gemm(x)
        x = fused_activation.fused_bias_activation_cuda(x, self.bias)
        x = groupnorm.group_norm_cuda(
            x, self.groupnorm_weight, self.groupnorm_bias,
            self.num_groups
        )
        return x
